package com.aoo.bcg.common.transaction;import java.lang.reflect.*;import java.sql.*;import java.util.concurrent.atomic.AtomicInteger;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class JdbcTransactionBoundaryTest{private static DataSource source(AtomicInteger commits,AtomicInteger rollbacks){Connection connection=(Connection)Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class[]{Connection.class},(p,m,a)->switch(m.getName()){case"getAutoCommit"->true;case"commit"->{commits.incrementAndGet();yield null;}case"rollback"->{rollbacks.incrementAndGet();yield null;}case"setAutoCommit","close"->null;case"isClosed"->false;default->throw new UnsupportedOperationException(m.getName());});return(DataSource)Proxy.newProxyInstance(DataSource.class.getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{if(m.getName().equals("getConnection"))return connection;throw new UnsupportedOperationException(m.getName());});}@Test void checkedUncheckedAndBusinessRejectionsRollback()throws Exception{var commits=new AtomicInteger();var rollbacks=new AtomicInteger();var boundary=new JdbcTransactionBoundary(source(commits,rollbacks));assertEquals("ok",boundary.execute(c->"ok"));assertThrows(java.io.IOException.class,()->boundary.execute(c->{throw new java.io.IOException("checked");}));assertThrows(IllegalArgumentException.class,()->boundary.execute(c->{throw new IllegalArgumentException("rejected");}));assertEquals(1,commits.get());assertEquals(2,rollbacks.get());}}
